<meta name="theme-color" content="#080a10">
<title>{{ $site->title ?: $site->name.' · Hosting' }}</title>
<meta name="description" content="{{ $site->description ?: 'Hosting powered by Nodexa.' }}">
<style>
:root{color-scheme:dark;--bg:#07090e;--surface:#0e121b;--surface2:#131824;--line:#242b3a;--text:#f4f6fb;--muted:#929caf;--primary:{{ $site->primary_color ?: '#745cff' }};--accent:{{ $site->accent_color ?: '#9a6dff' }};--green:#34d399;--red:#fb7185}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(circle at 20% -10%,color-mix(in srgb,var(--primary) 22%,transparent),transparent 35%),#07090e;color:var(--text);font:14px Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.wrap{width:min(1180px,calc(100% - 32px));margin:auto}a{text-decoration:none;color:inherit}button,input{font:inherit}.topbar{height:76px;border-bottom:1px solid rgba(37,44,58,.76);background:rgba(7,9,14,.82);backdrop-filter:blur(18px);position:sticky;top:0;z-index:30}.topin{height:100%;display:flex;align-items:center;justify-content:space-between;gap:20px}.brand{display:flex;align-items:center;gap:11px;font-weight:900;letter-spacing:.08em;font-size:18px}.mark{width:40px;height:40px;border-radius:11px;display:grid;place-items:center;background:linear-gradient(135deg,var(--primary),var(--accent));box-shadow:0 10px 30px color-mix(in srgb,var(--primary) 30%,transparent);font-size:18px}.brandName{max-width:260px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.nav{display:flex;align-items:center;gap:25px;color:#adb5c4;font-size:13px}.nav a:hover{color:white}.actions{display:flex;gap:9px}.btn{border:1px solid var(--line);background:#131925;color:#e8ebf1;border-radius:10px;padding:10px 14px;font-weight:800;cursor:pointer}.primary{border:0;background:linear-gradient(135deg,var(--primary),var(--accent));color:#fff;box-shadow:0 12px 32px color-mix(in srgb,var(--primary) 25%,transparent)}.cartBtn{position:relative}.cartCount{position:absolute;right:-7px;top:-7px;min-width:19px;height:19px;border-radius:20px;background:var(--accent);display:grid;place-items:center;font-size:10px;font-weight:900;padding:0 5px}.hero{padding:94px 0 65px}.heroGrid{display:grid;grid-template-columns:1.08fr .92fr;gap:60px;align-items:center}.pill{display:inline-flex;align-items:center;gap:8px;border:1px solid color-mix(in srgb,var(--primary) 35%,#242b3a);border-radius:999px;background:#141124;color:#c1b7ff;padding:7px 11px;font-size:11px;font-weight:800}.dot{width:7px;height:7px;border-radius:50%;background:var(--green)}h1{font-size:clamp(43px,6vw,72px);line-height:1.02;letter-spacing:-.045em;margin:18px 0}.grad{background:linear-gradient(100deg,#fff 5%,color-mix(in srgb,var(--accent) 65%,#fff),var(--primary));-webkit-background-clip:text;background-clip:text;color:transparent}.hero p{font-size:18px;line-height:1.65;color:#a4adbd;max-width:650px}.heroCtas{display:flex;gap:11px;flex-wrap:wrap;margin-top:28px}.heroCtas .btn{padding:13px 18px}.preview{border:1px solid #2b3342;border-radius:20px;background:linear-gradient(180deg,#111722,#0b0f16);box-shadow:0 30px 90px rgba(0,0,0,.4);padding:20px}.previewTop{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #252d39;padding-bottom:15px}.previewStatus{color:#70e6b9;font-size:11px}.previewGrid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px;margin:18px 0}.metric{background:#0d1118;border:1px solid #242c39;border-radius:10px;padding:15px}.metric small{color:#8490a3}.metric strong{display:block;font-size:22px;margin-top:6px}.console{height:130px;background:#080b10;border:1px solid #252d3a;border-radius:10px;padding:14px;overflow:hidden}.line{height:7px;border-radius:5px;background:#28303c;margin-bottom:9px}.line:nth-child(2){width:68%}.line:nth-child(3){width:84%;background:color-mix(in srgb,var(--primary) 45%,#27303d)}.section{padding:60px 0}.sectionHead{text-align:center;max-width:720px;margin:0 auto 35px}.eyebrow{color:var(--accent);font-size:11px;font-weight:900;letter-spacing:.15em}.section h2,.subTitle h1{font-size:38px;letter-spacing:-.03em;margin:8px 0 10px}.sectionHead p,.muted{color:var(--muted);line-height:1.65}.products{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.product{border:1px solid var(--line);background:linear-gradient(180deg,#111620,#0d1119);border-radius:16px;padding:22px;position:relative}.productIcon{width:45px;height:45px;border-radius:11px;background:color-mix(in srgb,var(--primary) 17%,#121620);display:grid;place-items:center;font-size:20px}.product h3{font-size:21px;margin:17px 0 5px}.product p{color:var(--muted);line-height:1.55;min-height:44px}.price{font-size:31px;font-weight:900;margin:20px 0 3px}.price small{font-size:12px;color:#8f99aa;font-weight:600}.features{display:grid;gap:9px;margin:20px 0;color:#b5bdca;font-size:12px}.features div:before{content:"✓";color:#69ddb4;font-weight:900;margin-right:8px}.product .btn{width:100%}.featureGrid{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}.feature{border:1px solid var(--line);border-radius:14px;background:#0d121a;padding:20px}.feature b{display:block;font-size:15px;margin:9px 0 6px}.feature p{margin:0;color:var(--muted);line-height:1.5;font-size:12px}.subPage{padding:55px 0 90px}.subTitle{margin-bottom:25px}.cartGrid,.checkoutGrid{display:grid;grid-template-columns:1fr 360px;gap:20px}.card{border:1px solid var(--line);background:#10151e;border-radius:15px}.cartList{padding:8px 18px}.cartItem{display:grid;grid-template-columns:1fr auto;gap:20px;padding:18px 2px;border-bottom:1px solid var(--line)}.cartItem:last-child{border:0}.cartItem h3{margin:0 0 5px}.cartItem p{margin:0;color:var(--muted);font-size:12px}.cartPrice{font-weight:900;font-size:17px;text-align:right}.remove{border:0;background:none;color:#fb8ba0;cursor:pointer;font-size:11px;margin-top:7px}.summaryCard,.formCard{padding:22px;height:max-content}.sumrow{display:flex;justify-content:space-between;gap:15px;padding:10px 0;color:#adb5c4;border-bottom:1px solid var(--line)}.sumrow.total{border:0;color:white;font-size:17px;font-weight:900;padding-top:16px}.summaryCard .btn{width:100%;margin-top:13px}.empty{padding:45px;text-align:center;color:var(--muted)}.formGrid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.wide{grid-column:1/-1}label span{display:block;color:#a6afbf;font-size:11px;font-weight:700;margin-bottom:7px}input{width:100%;padding:12px;border-radius:9px;border:1px solid #293243;background:#090d14;color:white;outline:none}.notice{background:#17132a;border:1px solid #3e3466;color:#bcb0e8;padding:12px 14px;border-radius:10px;margin-top:14px;font-size:12px;line-height:1.5}footer{border-top:1px solid var(--line);padding:36px 0 48px;margin-top:55px;color:#7f899b}.footerIn{display:flex;justify-content:space-between;gap:25px;flex-wrap:wrap}.footerLinks{display:flex;gap:20px}@media(max-width:900px){.nav{display:none}.heroGrid,.products,.cartGrid,.checkoutGrid{grid-template-columns:1fr}.featureGrid{grid-template-columns:1fr 1fr}.preview{order:-1}.actions .portal{display:none}}@media(max-width:560px){.wrap{width:min(100% - 22px,1180px)}.topbar{height:66px}.brand{font-size:15px}.mark{width:34px;height:34px}.hero{padding-top:54px}.hero p{font-size:15px}.featureGrid,.formGrid{grid-template-columns:1fr}.wide{grid-column:auto}.section h2,.subTitle h1{font-size:31px}}
</style>
</head>
<body>
@php
$panelUrl = $site->panel_url ?: config('app.url');
$initial = mb_strtoupper(mb_substr($site->name ?: 'N', 0, 1));
@endphp
<header class="topbar"><div class="wrap topin"><a class="brand" href="/"><span class="mark">{{ $initial }}</span><span class="brandName">{{ $site->name }}</span></a><nav class="nav"><a href="/#hosting">Hosting</a><a href="/#features">Fordele</a><a href="/faq">FAQ</a></nav><div class="actions"><a class="btn portal" href="{{ $panelUrl }}">Kundeportal</a><a class="btn cartBtn" href="/cart">Kurv <span id="cartCount" class="cartCount">0</span></a></div></div></header>
<main id="content"></main>
<footer><div class="wrap footerIn"><div><div class="brand" style="font-size:14px"><span class="mark" style="width:31px;height:31px">{{ $initial }}</span><span>{{ $site->name }}</span></div><p style="font-size:11px">Powered by Nodexa Multisite.</p></div><div class="footerLinks"><a href="/#hosting">Produkter</a><a href="/faq">FAQ</a><a href="{{ $panelUrl }}">Panel</a></div></div></footer>
<script>
const SITE=@json(['id'=>$site->id,'slug'=>$site->slug,'name'=>$site->name,'currency'=>$site->currency,'locale'=>$site->locale,'tagline'=>$site->tagline,'description'=>$site->description,'support_email'=>$site->support_email]);
const PRODUCTS=@json($products->map(fn($p)=>['id'=>$p->id,'slug'=>$p->slug,'name'=>$p->name,'description'=>$p->description,'price_cents'=>$p->price_cents,'billing_period'=>$p->billing_period,'type'=>$p->type,'features'=>$p->features ?? []])->values());
const PRODUCT_MAP=Object.fromEntries(PRODUCTS.map(p=>[p.slug,p]));
const CART_KEY=`nodexa_cart_${SITE.id}`;
const readCart=()=>{try{const v=JSON.parse(localStorage.getItem(CART_KEY)||'[]');return Array.isArray(v)?v:[]}catch{return[]}};
const writeCart=c=>{localStorage.setItem(CART_KEY,JSON.stringify(c));updateCount()};
const updateCount=()=>{const e=document.getElementById('cartCount');if(e)e.textContent=String(readCart().length)};
const money=cents=>new Intl.NumberFormat(SITE.locale||'da-DK',{style:'currency',currency:SITE.currency||'DKK'}).format((Number(cents)||0)/100);
const period=p=>p==='yearly'?'/år':p==='once'?'':'/md.';
function add(slug){const c=readCart();if(!c.includes(slug))c.push(slug);writeCart(c);location.href='/cart'}
function removeItem(slug){writeCart(readCart().filter(x=>x!==slug));render()}
function productCards(){return PRODUCTS.length?PRODUCTS.map((p,i)=>`<article class="product"><div class="productIcon">${p.type==='vps'?'▣':'◆'}</div><h3>${esc(p.name)}</h3><p>${esc(p.description||'')}</p><div class="price">${money(p.price_cents)} <small>${period(p.billing_period)}</small></div><div class="features">${(p.features||[]).map(f=>`<div>${esc(f)}</div>`).join('')}</div><button class="btn primary" onclick="add('${js(p.slug)}')">Tilføj til kurv</button></article>`).join(''):`<div class="card empty">Der er endnu ingen aktive produkter på denne storefront.</div>`}
function home(){return `<section class="hero"><div class="wrap heroGrid"><div><span class="pill"><span class="dot"></span> Powered by Nodexa</span><h1><span class="grad">${esc(SITE.tagline||'Hosting uden besvær.')}</span></h1><p>${esc(SITE.description||'Game server hosting samlet i ét moderne kontrolpanel.')}</p><div class="heroCtas"><a class="btn primary" href="#hosting">Se produkter</a><a class="btn" href="{{ $panelUrl }}">Åbn kundeportal</a></div></div><div class="preview"><div class="previewTop"><strong>Nodexa Game Panel</strong><span class="previewStatus">● Online</span></div><div class="previewGrid"><div class="metric"><small>CPU</small><strong>18%</strong></div><div class="metric"><small>RAM</small><strong>4.2 GB</strong></div></div><div class="console"><div class="line"></div><div class="line"></div><div class="line"></div></div></div></div></section><section class="section" id="hosting"><div class="wrap"><div class="sectionHead"><div class="eyebrow">HOSTING</div><h2>Vælg din løsning</h2><p>Produkter og priser hører kun til denne storefront.</p></div><div class="products">${productCards()}</div></div></section><section class="section" id="features"><div class="wrap"><div class="featureGrid"><div class="feature"><b>Automatisk provisionering</b><p>Ordrer kan oprette services direkte i Nodexa.</p></div><div class="feature"><b>Én kundeportal</b><p>Kunder styrer servere, databaser og backups samlet.</p></div><div class="feature"><b>Multisite</b><p>Hvert domæne har eget brand, katalog, priser og kurv.</p></div><div class="feature"><b>Separat branding</b><p>Farver, navn, domæner og indhold styres pr. site.</p></div></div></div></section>`}
function cart(){const items=readCart().map(x=>PRODUCT_MAP[x]).filter(Boolean);const total=items.reduce((a,p)=>a+p.price_cents,0);return `<section class="subPage"><div class="wrap"><div class="subTitle"><h1>Din kurv</h1><p class="muted">${esc(SITE.name)}</p></div><div class="cartGrid"><div class="card cartList">${items.length?items.map(p=>`<div class="cartItem"><div><h3>${esc(p.name)}</h3><p>${esc(p.description||'')}</p></div><div class="cartPrice">${money(p.price_cents)}<br><button class="remove" onclick="removeItem('${js(p.slug)}')">Fjern</button></div></div>`).join(''):`<div class="empty">Kurven er tom.</div>`}</div><aside class="card summaryCard"><h3>Ordreoversigt</h3><div class="sumrow"><span>Produkter</span><strong>${items.length}</strong></div><div class="sumrow total"><span>I alt</span><strong>${money(total)}</strong></div>${items.length?'<a class="btn primary" href="/checkout">Fortsæt til checkout</a>':''}</aside></div></div></section>`}
function checkout(){const items=readCart().map(x=>PRODUCT_MAP[x]).filter(Boolean);const total=items.reduce((a,p)=>a+p.price_cents,0);return `<section class="subPage"><div class="wrap"><div class="subTitle"><h1>Checkout</h1><p class="muted">Sikker checkout for ${esc(SITE.name)}</p></div><div class="checkoutGrid"><div class="card formCard"><h2>Kundeoplysninger</h2><div class="formGrid"><label><span>Fornavn</span><input></label><label><span>Efternavn</span><input></label><label class="wide"><span>E-mail</span><input type="email"></label></div><div class="notice">Betalingsgateway og automatisk provisionering kobles på Nodexa Billing. Kurv og katalog er allerede isoleret pr. storefront.</div></div><aside class="card summaryCard"><h3>Din ordre</h3>${items.map(p=>`<div class="sumrow"><span>${esc(p.name)}</span><strong>${money(p.price_cents)}</strong></div>`).join('')}<div class="sumrow total"><span>I alt</span><strong>${money(total)}</strong></div><button class="btn primary" disabled>Gå til betaling</button></aside></div></div></section>`}
function faq(){return `<section class="subPage"><div class="wrap"><div class="subTitle"><h1>FAQ</h1><p class="muted">${esc(SITE.name)}</p></div><div class="card formCard"><h2>Hvordan virker Nodexa?</h2><p class="muted">Nodexa samler storefront, kundeportal og game panel. Denne storefront er et separat site i samme installation.</p><h2>Har hver storefront sin egen kurv?</h2><p class="muted">Ja. Kurv, branding, katalog, priser, domæner og valuta er isoleret pr. storefront.</p>${SITE.support_email?`<h2>Support</h2><p class="muted">Kontakt ${esc(SITE.support_email)}</p>`:''}</div></div></section>`}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
function js(v){return String(v??'').replace(/['\\]/g,'\\$&')}
function render(){updateCount();const p=location.pathname.replace(/\/+$/,'')||'/';document.getElementById('content').innerHTML=p==='/cart'?cart():p==='/checkout'?checkout():p==='/faq'?faq():home()}
render();
</script>
</body>
</html>
